/bin/zsh -c "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { Schema, Either } from 'effect';
import { manifestSchema, importManifest } from './dist/index.js';
const parcel = { reference: ' p1 ', grams: 10, service: 'standard', extra: {} };
const input = { partner: ' shop ', parcels: [parcel, { reference: 'p2', grams: 1e20, service: 'express' }], extra: {} };
const expected = { partner: 'shop', parcels: [{ reference: 'p1', grams: 10, service: 'standard' }, { reference: 'p2', grams: 1e20, service: 'express' }] };
assert.deepEqual(Schema.decodeUnknownSync(manifestSchema)(input), expected);
const imported = importManifest(input);
assert.deepEqual(imported, { ok: true, manifest: expected });
assert.notEqual(imported.manifest, input);
assert.notEqual(imported.manifest.parcels, input.parcels);
assert.notEqual(imported.manifest.parcels[0], parcel);
assert.equal(input.partner, ' shop ');
assert.equal(parcel.reference, ' p1 ');
parcel.grams = 99;
input.parcels.reverse();
assert.deepEqual(imported.manifest, expected);
const valid = { reference: 'p', grams: 1, service: 'standard' };
const invalid = [undefined, null, false, 1, 'x', [], {}, { partner: 'x' }, { partner: 'x', parcels: [] }, { partner: ' ', parcels: [valid] }, { partner: 1, parcels: [valid] }, { partner: 'x', parcels: {} }, ...[undefined, null, [], {}, { ...valid, reference: ' ' }, { ...valid, reference: 1 }, ...[undefined, null, '1', 0, -1, 1.5, NaN, Infinity, -Infinity].map(grams => ({ ...valid, grams })), { ...valid, service: 'unknown' }, { ...valid, service: undefined }].map(p => ({ partner: 'x', parcels: [p] })), { partner: 'x', parcels: [valid, { ...valid, reference: ' p ' }] }];
for (const value of invalid) {
  assert.deepEqual(importManifest(value), { ok: false, reason: 'invalid-manifest' });
  assert.equal(Either.isLeft(Schema.decodeUnknownEither(manifestSchema)(value)), true);
}
console.log('Direct production decoder and importer checks passed: normalization, invalid values, uniqueness, order, and detached output.');
JS"

